	// Adaptive AI workflows — /adaptive (approval patterns, anomalies,
	// advisory suggestions, smart routing, auto-approve threshold, feedback loop)
	'adaptive.advisoryNote': 'Alles auf dieser Seite ist eine Empfehlung. Hier wurde noch kein Workflow geändert — eine Empfehlung wird erst wirksam, wenn jemand mit der passenden Rolle sie anwendet, über denselben protokollierten Weg wie eine manuelle Änderung.',
