	'adaptive.anomalies.heading': 'Auffälligkeiten',
	'adaptive.anomalies.intro': 'Rechnungen in Prüfung, die außerhalb des etablierten Musters ihres Lieferanten liegen — beim Betrag, bei der freigebenden Person oder bei der Wartezeit. Nur lesend: eine Markierung hier löst nichts aus und blockiert nichts.',
