	'adaptive.feedback.heldBack': 'Die Freigabehistorie trägt eine Anhebung, doch die Rückkopplung hält sie zurück, weil automatisch freigegebene Rechnungen revidiert werden. Die angepasste Zahl ist die, auf die eine Anwendung wirken würde.',
	'adaptive.feedback.insufficientShort': 'Noch zu wenige automatisch freigegebene Rechnungen für eine Quote.',
	'adaptive.feedback.intro': 'Was mit den automatisch freigegebenen Rechnungen tatsächlich passiert ist — wie viele später storniert, korrigiert oder abgelehnt wurden — zurückgeführt in die Schwellenempfehlung, damit sie zurückgeht, wenn die Automatik überstimmt wird.',
