	'adaptive.feedback.refresh': 'Aktualisieren',
	'adaptive.lede': 'Was Ihre eigene Freigabehistorie darüber aussagt, wie dieser Mandant Rechnungen freigibt — wer am schnellsten ist, welche Lieferanten konsistent sind, welche Rechnungen außerhalb des üblichen Musters ihres Lieferanten liegen und ob die Schwelle für die automatische Freigabe sicher angehoben werden könnte. Deterministische Statistik über Ihre eigenen Daten: kein KI-Modell, nichts wird versendet, bei jedem Aufruf neu berechnet.',
